                case RecordTypeInts.OPDS:
                {
                    this.ObjectPlacementDefaults = BinaryOverlayList.FactoryByArray<IObjectPlacementDefaultGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => ObjectPlacementDefaultBinaryOverlay.ObjectPlacementDefaultFactory(new OverlayStream(s, p), p, recConv),
